const D = { rings: 22, scale: 1, energy: .6, density: .5, cut: .72, hue: 26, speed: 1, x: .3, y: .5, alpha: 1, style: 'oiled', act: 'plane', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255,(g+m)*255,(l+m)*255]; };
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height;
const sty=P.style, act=P.act;
const nRing=cl(P.rings,3,60), sc=cl(P.scale,.4,2.4), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4), en=cl(P.energy,0,1);
const cut=cl(P.cut,0,1), H=md(P.hue,360), T=K.t*spd;
const TD=K.t*(.45+.55*Math.min(spd,3));

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;

// ---- seeded wrapping fBm field (once per seed) ----
const NZ=160;
if(S.nzK!==P.seed || !S.nz){ S.nzK=P.seed; const F=new Float32Array(NZ*NZ); let amp=1, tot=0;
  for(let o=0;o<4;o++){ const per=4<<o, cell=NZ/per;
    const lv=new Float32Array(per*per);
    for(let k=0;k<per*per;k++) lv[k]=fr(o*977.3+k*1.317+3.7);
    for(let j=0;j<NZ;j++){ const gy=j/cell, jy=Math.floor(gy), fy=gy-jy, vv=fy*fy*(3-2*fy);
      const j0=(jy%per)*per, j1=((jy+1)%per)*per;
      for(let i=0;i<NZ;i++){ const gx=i/cell, ix=Math.floor(gx), fx=gx-ix, uu=fx*fx*(3-2*fx);
        const i0=ix%per, i1=(ix+1)%per;
        const a=lv[j0+i0], b=lv[j0+i1], c=lv[j1+i0], d=lv[j1+i1];
        F[j*NZ+i]+=amp*(a+(b-a)*uu+(c-a)*vv+(a-b-c+d)*uu*vv); } }
    tot+=amp; amp*=0.52; }
  for(let k=0;k<NZ*NZ;k++) F[k]=F[k]/tot;
  S.nz=F; }
const NF=S.nz, CEL=NZ/4;
const nzAt=(x,y)=>{ x*=CEL; y*=CEL;
  let xi=Math.floor(x), yi=Math.floor(y); const fx=x-xi, fy=y-yi;
  xi=md(xi,NZ); yi=md(yi,NZ); const x1=(xi+1)%NZ, y1=(yi+1)%NZ, r0=yi*NZ, r1=y1*NZ;
  const a=NF[r0+xi], b=NF[r0+x1], c=NF[r1+xi], d=NF[r1+x1];
  return a+(b-a)*fx+(c-a)*fy+(a-b-c+d)*fx*fy; };

const BW=Math.max(340, Math.min(480, Math.round(W/2.8))), BH=cl(Math.round(BW*Hh/Math.max(1,W)),60,720);
if(!S.g || S.gk!==BW+'x'+BH){ if(S.g&&S.g.remove)S.g.remove();
  S.g=createGraphics(BW,BH); S.gk=BW+'x'+BH; S.row=new Float32Array(BW*3); }
const G=S.g, ROW=S.row;

// ---- dramaturgy ----
const sec=((K.section|0)%8+8)%8;
let feedRate, rayAmt, seasonF;
if(act==='season'){ feedRate=.42; rayAmt=.8; seasonF=.82+.30*Math.sin(sec*.9+T*.017); }
else if(act==='figure'){ feedRate=.30; rayAmt=1.9; seasonF=1; }
else { feedRate=1; rayAmt=1; seasonF=1; }

// ---- the board runs past: a MONOTONIC feed. It never comes back, so it can never re-phase.
const xoff=.0135*TD*feedRate + .05*Math.sin(TD*.031) + .02*Math.sin(TD*.077+1.3);
// raking light across the face — this is what makes the ray fleck flash (chatoyance)
const lAz=cl(P.x,0,1)*TAU + .0105*TD + .22*Math.sin(TD*.047+.4) + .11*Math.sin(TD*.109+2.1);
const lx=Math.cos(lAz), ly=Math.sin(lAz);
const lEl=(cl(P.y,0,1)-.5)*1.3 + .16*Math.sin(TD*.061+1.1) + .07*Math.sin(TD*.127+2.8) + .03*K.swell;

// ---- style ----
let EW, LW, KNOT, spTint, xray=0, inkish=0, charred=0, grainAmt=.06;
if(sty==='bleached'){ EW=hsb2rgb(H+8,11,86); LW=hsb2rgb(H+4,17,58); KNOT=hsb2rgb(H+2,20,40); spTint=[248,250,255]; grainAmt=.05; }
else if(sty==='charred'){ EW=hsb2rgb(H-6,16,17); LW=hsb2rgb(H-2,26,7); KNOT=hsb2rgb(H,30,5); spTint=[255,214,150]; charred=1; grainAmt=.10; }
else if(sty==='xray'){ EW=hsb2rgb(H+180,4,22); LW=hsb2rgb(H+180,3,92); KNOT=hsb2rgb(H+180,5,99); spTint=[255,255,255]; xray=1; grainAmt=.03; }
else if(sty==='ink'){ EW=hsb2rgb(H+4,7,85); LW=hsb2rgb(H-6,26,20); KNOT=hsb2rgb(H-8,30,13); spTint=[250,246,236]; inkish=1; grainAmt=.13; }
else { EW=hsb2rgb(H+3,42,72); LW=hsb2rgb(H-6,58,31); KNOT=hsb2rgb(H-10,62,18); spTint=[255,236,196]; grainAmt=.06; }

// ---- growth-ring profile LUT: earlywood slowly densifies, latewood is a sharp dark band ----
const lwF=cl(.74-.26*dens,.24,.88);
const pkey=Math.round(lwF*200)+'|'+(xray?1:0);
if(S.pk!==pkey || !S.pr){ S.pk=pkey; const NP=512; S.pr=new Float32Array(NP); S.pd=new Float32Array(NP);
  for(let k=0;k<NP;k++){ const f=k/NP; let v;
    if(f<lwF){ const u=f/lwF; v=.16+.30*u*u; }                       // earlywood
    else { const u=(f-lwF)/Math.max(.02,1-lwF); v=.50+.50*Math.pow(u,.55); } // latewood
    S.pr[k]=v; }
  for(let k=0;k<NP;k++){ const a=S.pr[(k+511)%NP], b=S.pr[(k+1)%NP]; S.pd[k]=(b-a)*.5*NP; }
}
const PR=S.pr, PD=S.pd;

// ---- pith geometry: the log's heart wanders down its length; `cut` sets how far the
// board face lies off it — 0 = through the heart (quartersawn, straight grain + ray fleck),
// 1 = way off it (flatsawn, the cathedral arches). This is the real sawing geometry.
const ringF=nRing/Math.max(.10,.62*sc);
const dOff=(.02+1.05*cut*cut)*sc*seasonF;
const ph1=fr(11)*TAU, ph2=fr(12)*TAU;
const asp=W/Math.max(1,Hh);
const rayOn=(1-cut)*(1-cut)*rayAmt;   // rays only show on a radial face — real anatomy
const KPER=1.6*sc;
const nKnot=Math.round(dens*2.4);

G.loadPixels();
const px=G.pixels, sR=spTint[0], sG=spTint[1], sB=spTint[2];
const spAmt=(.18+.72*en)*(.6+.6*K.intensity)+S.tre*.22*en;
const gAmt=grainAmt*(.5+.9*dens);

// per-column: pith position + face offset only depend on position along the board
for(let i=0;i<BW;i++){
  const sx=(i/BW)*asp*1.0+xoff;
  ROW[i*3]=(nzAt(sx*.62+3.3, 11.31)-.5)*1.35*sc;               // pith drift across the board
  ROW[i*3+1]=dOff*(1+(nzAt(sx*.41+21.7, 27.13)-.5)*.55);       // face-to-heart distance
  ROW[i*3+2]=sx;
}

for(let j=0;j<BH;j++){
  const sy=(j/BH-.5);
  for(let i=0;i<BW;i++){
    const sx=ROW[i*3+2], pyv=ROW[i*3], dv=ROW[i*3+1];
    const dy=sy-pyv;
    let rr=Math.sqrt(dy*dy+dv*dv);
    // knots on a jittered periodic lattice — they scroll in from the end of the board
    let knotV=0, pull=0;
    if(nKnot>0){
      const c0=Math.floor(sx/KPER);
      for(let c=c0-1;c<=c0+1;c++){
        const hx=fr(c*13.7+500), hy=fr(c*13.7+501), hr=fr(c*13.7+502), hg=fr(c*13.7+503);
        if(hg>nKnot*.34) continue;
        const kx=(c+hx)*KPER, ky=(hy-.5)*.72, kr=(.035+.055*hr)*sc;
        const ddx=sx-kx, ddy=sy-ky, dk=Math.sqrt(ddx*ddx+ddy*ddy);
        pull+=kr*kr*2.6/(dk*dk+kr*kr*.55);            // rings get dragged toward the branch
        if(dk<kr) knotV=Math.max(knotV,cl(1-dk/kr,0,1));
      }
    }
    rr+=pull*.30;
    // ring widths vary year to year, consistently at every point on the same ring
    let ring=rr*ringF;
    ring+=.85*Math.sin(ring*.29+ph1)+.38*Math.sin(ring*.81+ph2);
    const f=ring-Math.floor(ring);
    let ki=(f*512)|0; if(ki<0)ki=0; if(ki>511)ki=511;
    const dv2=PR[ki], slopeR=PD[ki];
    // ray fleck: medullary rays, only on a radial face, flashing as the light rakes
    let ray=0;
    if(rayOn>.02){
      const rf=nzAt(sx*26+61.1, sy*3.4+7.7);
      const rf2=nzAt(sx*9.1+13.3, sy*1.7+41.9);
      ray=Math.pow(cl((rf*.75+rf2*.55)-.52,0,1),1.4)*rayOn*(.45+1.25*cl(.5+lEl*.9,0,1));
    }
    // surface: the grain has relief (latewood stands proud of the softer earlywood)
    const slope=cl(slopeR*(.006+.010*en)*(dy>0?1:-1)*ly+slopeR*.004*lx,-4,4);
    const lam=cl(.62-slope*.5,0,1.35);
    const gn=(nzAt(sx*34+7.1, sy*34+2.9)-.5)*gAmt+(nzAt(sx*90+5.5, sy*7.1+1.1)-.5)*gAmt*.7;
    let R,Gc,B;
    const m=cl(dv2,0,1);
    R=EW[0]+(LW[0]-EW[0])*m; Gc=EW[1]+(LW[1]-EW[1])*m; B=EW[2]+(LW[2]-EW[2])*m;
    if(knotV>0){ const kk=Math.pow(knotV,.6);
      R=R+(KNOT[0]-R)*kk; Gc=Gc+(KNOT[1]-Gc)*kk; B=B+(KNOT[2]-B)*kk; }
    const sl=xray?1:(inkish?(.70+.45*lam):(.42+.80*lam));
    R*=sl*(1+gn); Gc*=sl*(1+gn); B*=sl*(1+gn);
    if(!xray&&!inkish){
      // chatoyance — the figure lights up where the light rakes it, and the fleck flashes
      const sh=sx*lx*.35+sy*ly;
      const sheen=spAmt/(1+Math.pow((sh-lEl*1.1)*2.2,2)*2.6);
      const sp2=(sheen*(.35+.7*(1-m))+ray*.55*spAmt*2.2)*72;
      R+=sR*sp2/255; Gc+=sG*sp2/255; B+=sB*sp2/255;
      if(charred){ // shou sugi ban — the soft earlywood burns out, embers glow in the checks
        const ch=Math.pow(cl((nzAt(sx*17+3.1, sy*17+9.9)-.46)*3.4,0,1),1.2)*(1-m);
        R+=ch*96; Gc+=ch*34; B+=ch*6;
      }
    } else if(xray){ R*=(1+ray*.5); Gc*=(1+ray*.5); B*=(1+ray*.5); }
    else { R+=ray*40; Gc+=ray*38; B+=ray*34; }
    const vx=(i/BW-.5), vy=(j/BH-.5), vg=1-.30*(vx*vx*1.1+vy*vy*1.5);
    R*=vg; Gc*=vg; B*=vg;
    const o=(j*BW+i)*4;
    px[o]=R<0?0:R>255?255:R; px[o+1]=Gc<0?0:Gc>255?255:Gc; px[o+2]=B<0?0:B>255?255:B; px[o+3]=255;
  }
}
G.updatePixels();

noStroke();
if(al<1){ push(); drawingContext.globalAlpha=al; image(G,0,0,W,Hh); pop(); }
else image(G,0,0,W,Hh);
const dc=drawingContext;
blendMode(BLEND); dc.globalAlpha=1; dc.shadowBlur=0; noStroke(); noTint();
